/**
 * Swizzled @theme/DocItem/Metadata (eject of theme-classic v3.10.2).
 *
 * ONE CHANGE: when a doc declares no `image` of its own, the page falls back to its SECTION's
 * social card rather than to the single site-wide one.
 *
 * WHY. `themeConfig.image` set one `og:image` for all 236 routes, so a link to the `set_wifi`
 * reference and a link to the FAQ index previewed identically — the card identified the product
 * and said nothing about the page. Fourteen section cards are generated by
 * `scripts/site/generate-social-cards.mjs` from `social-cards-manifest.json`; this component is
 * what routes a page to the right one.
 *
 * LONGEST PREFIX WINS, and that is load-bearing rather than tidy: `/api-reference/mqtt/` has to
 * beat `/api-reference/`, and `/resources/glossary/` has to beat `/resources/`. Sorting the
 * manifest by descending prefix length once at module scope makes the first match the right one.
 *
 * THE MANIFEST IS IMPORTED, NOT DUPLICATED. The same file the generator reads is the file this
 * resolves against, so a section renamed in one place cannot silently keep the old card in the
 * other — and `--check` fails the build if the PNGs and the manifest disagree.
 *
 * A DOC'S OWN `image:` STILL WINS. The fallback only fills a gap; nothing here overrides an
 * explicit front-matter image, which is what a page with a bespoke card would set.
 */
import React, { type ReactNode } from 'react';
import { PageMetadata } from '@docusaurus/theme-common';
import { useDoc } from '@docusaurus/plugin-content-docs/client';
import { useLocation } from '@docusaurus/router';
import useBaseUrl from '@docusaurus/useBaseUrl';
import manifest from '@site/scripts/site/social-cards-manifest.json';

type Section = { key: string; routePrefix: string };

/* Descending by prefix length, computed once — see LONGEST PREFIX WINS above. */
const SECTIONS: Section[] = [...(manifest.sections as Section[])].sort(
  (a, b) => b.routePrefix.length - a.routePrefix.length,
);

function sectionKeyFor(pathname: string, baseUrl: string): string | undefined {
  // useLocation().pathname carries the baseUrl; the manifest's prefixes do not.
  const route = pathname.startsWith(baseUrl) ? pathname.slice(baseUrl.length - 1) : pathname;
  return SECTIONS.find((s) => route === s.routePrefix || route.startsWith(s.routePrefix))?.key;
}

/* Literal paths, deliberately not a template string: scripts/site/lint-static-orphans.mjs
 * finds a static/ asset only by its exact basename, so `${key}.png` reads as 11 orphans and
 * fails CI. Same reason and same fix as CARD_PHOTO in src/pages/index.tsx. */
const SOCIAL_CARD: Record<string, string> = {
  guides: '/img/social/guides.png',
  'api-reference': '/img/social/api-reference.png',
  mqtt: '/img/social/mqtt.png',
  rest: '/img/social/rest.png',
  resources: '/img/social/resources.png',
  glossary: '/img/social/glossary.png',
  faqs: '/img/social/faqs.png',
  'quick-reference': '/img/social/quick-reference.png',
  'additional-reference': '/img/social/additional-reference.png',
  'api-changelog': '/img/social/api-changelog.png',
  support: '/img/social/support.png',
};

export default function DocItemMetadata(): ReactNode {
  const { metadata, frontMatter, assets } = useDoc();
  const { pathname } = useLocation();
  const baseUrl = useBaseUrl('/');
  const key = sectionKeyFor(pathname, baseUrl);
  const fallback = useBaseUrl((key && SOCIAL_CARD[key]) || '/img/social/home.png');

  return (
    <PageMetadata
      title={metadata.title}
      description={metadata.description}
      keywords={frontMatter.keywords}
      image={assets.image ?? frontMatter.image ?? fallback}
    />
  );
}
